from scipy.optimize import least_squares
one=np.ones_like(t)
def build3(b,extra):
    E=np.exp(-b*t)
    base=[one,t,E,P,P**2,P**3,t*P,t*P**2,E*P,E*P**2,E*P**3,t*P**3,t*E,t*E*P,t*E*P**2,E**2,E**2*P,E**2*P**2]
    ex={'logP':np.log(P),'PlogP':P*np.log(P),'P2logP':P**2*np.log(P),'invP':1/P,'sqrtP':np.sqrt(P),'P4':P**4,'tlogP':t*np.log(P),'tPlogP':t*P*np.log(P)}
    return np.column_stack(base+[ex[e] for e in extra])
def rr(p,extra):
    Xm=build3(p[0],extra); c=np.linalg.lstsq(Xm,dP_dt,rcond=None)[0]
    return dP_dt-Xm@c
